import React, { useEffect, useState } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import { clearLastVisitedUrls } from "../../utils/redirectUtils";

export default function PublicAccountActions() {
  const navigate = useNavigate();
  const location = useLocation();
  const [isLoggedIn, setIsLoggedIn] = useState(() => {
    try {
      return !!(
        sessionStorage.getItem("accessToken") ||
        localStorage.getItem("accessToken")
      );
    } catch {
      return false;
    }
  });

  const getDashboardUrl = () => {
    try {
      const role = (
        sessionStorage.getItem("primaryType") ||
        localStorage.getItem("primaryType") ||
        ""
      ).toUpperCase();
      const userId =
        sessionStorage.getItem("userId") ||
        localStorage.getItem("userId") ||
        "";

      if (["ADMIN", "HELPDESKADMIN", "SUPERADMIN", "PRIMARYADMIN"].includes(role)) {
        return "/oxyloansadmindashboard";
      }
      if (role === "LENDER") {
        return userId ? `/lenderAIDashboard/${userId}` : "/ai/portfolio";
      }
      if (role === "PARTNER") {
        return "/patnerdashboard";
      }
      if (role === "BORROWER") {
        if (String(userId).trim() === "41682") {
          return "/instant-borrower-dashboard";
        }
        return "/borrowerDashboard";
      }
      return "/dashboard";
    } catch {
      return "/landing";
    }
  };

  const [dashboardUrl, setDashboardUrl] = useState(getDashboardUrl);

  useEffect(() => {
    const syncAuth = () => {
      const authed = !!(
        sessionStorage.getItem("accessToken") ||
        localStorage.getItem("accessToken")
      );
      setIsLoggedIn(authed);
      if (authed) {
        setDashboardUrl(getDashboardUrl());
      }
    };

    syncAuth();
    window.addEventListener("storage", syncAuth);
    return () => window.removeEventListener("storage", syncAuth);
  }, [location.pathname]);

  const handleLogout = (e) => {
    if (e && e.preventDefault) e.preventDefault();
    clearLastVisitedUrls();
    try {
      sessionStorage.clear();
      localStorage.clear();
      clearLastVisitedUrls();
    } catch (err) {
      // ignore
    }
    setIsLoggedIn(false);
    navigate("/landing");
  };

  return (
    <div className="oxy-float-accounts" role="group" aria-label="Account">
      {isLoggedIn ? (
        <>
          <Link className="oxy-float-join" to={dashboardUrl}>Dashboard</Link>
          <button className="oxy-float-login" type="button" onClick={handleLogout}>Logout</button>
        </>
      ) : (
        <>
          <Link className="oxy-float-join" to="/userType">Join Now</Link>
          <Link className="oxy-float-login" to="/loginotp">Login</Link>
        </>
      )}
    </div>
  );
}
