import React from "react";
import { Link } from "react-router-dom";
import { FaArrowRight } from "react-icons/fa";
import lending from "./media/lending.webp";
import borrowing from "./media/borrowing.webp";
import { usePreviewTilt } from "./useScrollChoreography";

const gateways = [
  {
    theme: "lender-theme", title: "Start Lending", action: "Start lending", to: "/register", image: lending,
    description: "Lend to creditworthy borrowers and be part of the OxyLoans P2P ecosystem.",
  },
  {
    theme: "borrower-theme", title: "Start Borrowing", action: "Start borrowing", to: "/borrower_register", image: borrowing,
    description: "Get quick access to funds through a simple, transparent and completely digital process.",
  },
];

function Gateway({ theme, title, action, to, image, description }) {
  const tilt = usePreviewTilt();
  return (
    <article className={`oxy-gateway-card ${theme}`} {...tilt} data-preview-reveal="">
      <div className="oxy-gateway-info">
        <h2 className="oxy-gateway-title">{title}</h2>
        <p className="oxy-gateway-desc">{description}</p>
        <Link to={to} className="oxy-circle-arrow-btn">{action} <FaArrowRight aria-hidden="true" /></Link>
      </div>
      <div className="oxy-gateway-3d-visual" aria-hidden="true">
        <span className="oxy-gateway-orbit"><i /></span>
        <span className="oxy-film-product-camera">
          <img className="oxy-film-product" src={image} alt="" loading="lazy" decoding="async" width="600" height="600" />
        </span>
      </div>
    </article>
  );
}

export default function PreviewGatewayCards() {
  return (
    <section className="oxy-gateways-section" aria-label="Borrowing and lending" data-preview-loop="">
      <div className="oxy-preview-container">
        <div className="oxy-gateways-grid">{gateways.map(item => <Gateway key={item.to} {...item} />)}</div>
      </div>
    </section>
  );
}
