    const handleScroll = () => {
      const y = window.scrollY;
      setShowBackToTop(y > 400);

      const totalHeight = document.documentElement.scrollHeight - window.innerHeight;
      if (totalHeight > 0) {
        scrollProgress.set(y / totalHeight);
      }
    };

