import { useEffect, useRef, useSyncExternalStore } from "react";

const motionPreference = "(prefers-reduced-motion: reduce)";

function subscribeToMotionPreference(notify) {
  const query = window.matchMedia(motionPreference);
  query.addEventListener("change", notify);
  return () => query.removeEventListener("change", notify);
}

export function usePreviewReducedMotion() {
  return useSyncExternalStore(subscribeToMotionPreference, () => window.matchMedia(motionPreference).matches, () => true);
}

// Reveals run once. Ambient effects may resume when their section returns to view.
export default function useScrollChoreography(rootRef, reducedMotion) {
  useEffect(() => {
    const root = rootRef.current;
    if (!root || reducedMotion || !window.IntersectionObserver) return;
    const observer = new IntersectionObserver(entries => {
      for (const { target, isIntersecting } of entries) {
        const looping = target.hasAttribute("data-preview-loop");
        if (looping) target.toggleAttribute("data-onstage", isIntersecting);
        if (isIntersecting && target.hasAttribute("data-preview-reveal")) {
          target.setAttribute("data-revealed", "");
          if (!looping) observer.unobserve(target);
        }
      }
    });
    const elements = root.querySelectorAll("[data-preview-reveal], [data-preview-loop]");
    elements.forEach(element => observer.observe(element));
    return () => {
      observer.disconnect();
      elements.forEach(element => element.removeAttribute("data-onstage"));
    };
  }, [rootRef, reducedMotion]);
}

// CSS consumes the two angles on the artwork only. Touch scrolling stays native.
export function usePreviewTilt() {
  const frame = useRef(0);
  useEffect(() => () => cancelAnimationFrame(frame.current), []);
  return {
    onPointerMove(event) {
      if (event.pointerType !== "mouse" || !window.matchMedia("(hover: hover) and (prefers-reduced-motion: no-preference)").matches) return;
      const { currentTarget, clientX, clientY } = event;
      cancelAnimationFrame(frame.current);
      frame.current = requestAnimationFrame(() => {
        const rect = currentTarget.getBoundingClientRect();
        currentTarget.style.setProperty("--preview-yaw", `${6 * ((clientX - rect.left) / rect.width - 0.5)}deg`);
        currentTarget.style.setProperty("--preview-pitch", `${4 * (0.5 - (clientY - rect.top) / rect.height)}deg`);
      });
    },
    onPointerLeave({ currentTarget }) {
      cancelAnimationFrame(frame.current);
      currentTarget.style.removeProperty("--preview-yaw");
      currentTarget.style.removeProperty("--preview-pitch");
    },
  };
}
