import React, { createContext, useContext, useEffect, useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import {
  FaFacebookF, FaTwitter, FaLinkedinIn, FaYoutube, FaWhatsapp,
} from "react-icons/fa";
import PreviewFloatingHeader from "../pages/LandingPreview/PreviewFloatingHeader";
import "./LandingHeader.css";

export const EmbeddedPublicNavigation = createContext(false);

export default function LandingHeader({ showDisclaimerTicker = true, showProgressBar = true, showSocialDock = true }) {
  const embedded = useContext(EmbeddedPublicNavigation);
  const navigate = useNavigate();
  const location = useLocation();
  const [scrollProgress, setScrollProgress] = useState(0);
  useEffect(() => {
    if (embedded || !showProgressBar) return;
    const update = () => {
      const distance = document.documentElement.scrollHeight - document.documentElement.clientHeight;
      setScrollProgress(distance > 0 ? Math.min(100, window.scrollY / distance * 100) : 0);
    };
    update();
    window.addEventListener("scroll", update, { passive: true });
    return () => window.removeEventListener("scroll", update);
  }, [embedded, showProgressBar]);

  if (embedded) return null;

  return (
    <div className="oxy-header-wrapper oxy-public-navigation">
      <div className="oxy-preview-root oxy-preview-chrome oxy-original-navigation">
        <PreviewFloatingHeader key={location.pathname + location.search + location.hash} preview={false} showDisclaimerTicker={showDisclaimerTicker} onDirections={() => navigate("/rbi-directions")} />
      </div>
      {showProgressBar && (
        <div className="oxy-landing-scroll-progress" style={{ width: scrollProgress + "%" }} aria-hidden="true" />
      )}
      {showSocialDock && (
        <aside className="oxy-landing-social-dock" aria-label="Social Media Links">
          <a
            href="https://www.facebook.com/OxyLoans/"
            target="_blank"
            rel="noopener noreferrer"
            className="soc-fb"
            title="Facebook"
          >
            <FaFacebookF />
          </a>
          <a
            href="https://twitter.com/oxyloans"
            target="_blank"
            rel="noopener noreferrer"
            className="soc-tw"
            title="Twitter"
          >
            <FaTwitter />
          </a>
          <a
            href="https://www.linkedin.com/company/oxyloans/"
            target="_blank"
            rel="noopener noreferrer"
            className="soc-li"
            title="LinkedIn"
          >
            <FaLinkedinIn />
          </a>
          <a
            href="https://www.youtube.com/@oxyloans"
            target="_blank"
            rel="noopener noreferrer"
            className="soc-yt"
            title="YouTube"
          >
            <FaYoutube />
          </a>
          <a
            href="https://api.whatsapp.com/send?phone=919966888825"
            target="_blank"
            rel="noopener noreferrer"
            className="soc-wa"
            title="WhatsApp"
          >
            <FaWhatsapp />
          </a>
        </aside>
      )}

    </div>
  );
}
