import React, { useEffect, useRef, useState } from "react";
import { Link } from "react-router-dom";
import { FaEnvelope, FaPhoneAlt, FaBars, FaChevronDown, FaExternalLinkAlt, FaTimes } from "react-icons/fa";
import PublicAccountActions from "../../Header/PublicAccountActions";
import LoginDisclaimerTicker from "../Authentication/LoginDisclaimerTicker";
import logo from "../../../assets/img/oxylogodashboard.png";
import { previewHome, publicPreviewHref } from "./publicPreviewPaths";
import "./PreviewFloatingHeader.css";

const menus = {
  Team: { Team: [["About us", "#about-us"], ["Management", "/team-management"], ["Advisory Board", "/advisory-team"]] },
  Lend: { Lend: [["Lender", "/lender"], ["Start lending", "/register"], ["Lender FAQs", "/faqs?category=lender"], ["Know Your Earnings", "/know-your-earnings"], ["Lender Testimonials", "#testimonials"]] },
  Borrow: { Borrow: [["Borrower", "/borrower"], ["Start borrowing", "/borrower_register"]] },
  Resources: {
    "Loan Products": [["Personal Loans", "/personal-loans"], ["SME Loans", "/sme-loans"], ["Business Loans", "/business-loans"], ["International Expansion Loans", "/international-business-expansion-loans"], ["Motor Loans", "/motor-loans"], ["Travel Loans", "/travel-loans"]],
    "Partner Network": [["Partner Registration", "/register"], ["Partner Login", "/loginotp"]],
    "Calculators & Tools": [["Loan EMI Calculator", "/emicalculator"], ["Loan Performance", "/loan-performance"], ["Latest EGM Notice", "/latest-egm-notice"]],
    "Media & Support": [["How It Works", "/how-it-works"], ["Frequently Asked Questions", "/faqs"], ["Video Library", "https://www.youtube.com/@oxyloans"], ["OxyLoans Blog", "/blogs"], ["Testimonials & Reviews", "#testimonials"], ["Contact Us", "/contact-us"]],
  },
  "Knowledge Center": { Learn: [["Knowledge Center", "#knowledge-center"], ["Lender FAQs", "/faqs?category=lender"], ["Borrower FAQs", "/faqs?category=borrower"], ["Know Your Fees", "/know-your-fees"], ["Know Your Tax", "/know-your-tax"], ["Know Your Earnings", "/know-your-earnings"], ["How It Works", "/how-it-works"], ["Transparency and Disclosure Requirements", "/transparency"], ["Grievances Redressal Mechanism", "/grievance-redressal-mechanism"], ["RBI Directions", "/rbi-directions"], ["Privacy Policy", "/privacy-policy"], ["YouTube", "https://www.youtube.com/@oxyloans"]] },
};

const originalSections = { "#about-us": "#about-section", "#testimonials": "#success-stories" };

export default function PreviewFloatingHeader({ onDirections, preview = true, showDisclaimerTicker = true }) {
  const home = preview ? previewHome : "/landing";
  const destination = url => preview ? publicPreviewHref(url) : url;
  const [scrolled, setScrolled] = useState(() => window.scrollY > 24);
  useEffect(() => {
    const update = () => setScrolled(window.scrollY > 24);
    window.addEventListener("scroll", update, { passive: true });
    return () => window.removeEventListener("scroll", update);
  }, []);
  const [open, setOpen] = useState(null);
  const [mobile, setMobile] = useState(false);
  const header = useRef(null);
  const toggle = useRef(null);
  const trigger = useRef(null);
  function close() {
    setOpen(null);
    setMobile(false);
  }
  useEffect(() => {
    function dismiss(event) {
      if (!header.current.contains(event.target)) close();
    }
    const breakpoint = window.matchMedia("(max-width: 1280px)");
    breakpoint.addEventListener("change", close);
    document.addEventListener("pointerdown", dismiss);
    return () => {
      breakpoint.removeEventListener("change", close);
      document.removeEventListener("pointerdown", dismiss);
    };
  }, []);

  return <div className="oxy-float-slot" data-notice={showDisclaimerTicker}>
    {showDisclaimerTicker && (
      <div className="oxy-float-notice">
        <LoginDisclaimerTicker />
        <a href="mailto:support@oxyloans.com" aria-label="Email OxyLoans"><FaEnvelope /></a>
        <a href="tel:+919966888825" aria-label="Call OxyLoans"><FaPhoneAlt /></a>
      </div>
    )}
    <header className="oxy-float-header" data-scrolled={scrolled} ref={header}
      onBlur={event => { if (!event.currentTarget.contains(event.relatedTarget)) close(); }}
      onKeyDown={event => {
        if (event.key !== "Escape") return;
        if (open) { setOpen(null); trigger.current?.focus(); }
        else if (mobile) { close(); toggle.current.focus(); }
      }}>
      <Link to={home} aria-label="OxyLoans home" onClick={close}><img src={logo} alt="OxyLoans" /></Link>
      <button className="oxy-float-toggle" type="button" aria-expanded={mobile} aria-controls="oxy-preview-navigation" aria-label={mobile ? "Close menu" : "Open menu"} ref={toggle}
        onClick={() => { setMobile(!mobile); setOpen(null); }}>{mobile ? <FaTimes /> : <FaBars />}</button>
      <nav id="oxy-preview-navigation" aria-label="Main navigation" data-mobile-open={mobile} data-lenis-prevent="">
        <Link to={home} onClick={close}>Home</Link>
        {Object.entries(menus).map(([name, groups], index) => (
          <div key={name} className="oxy-float-group">
            <button type="button" aria-expanded={open === name} aria-controls={`oxy-float-menu-${index}`}
              onClick={event => { trigger.current = event.currentTarget; setOpen(open === name ? null : name); }}>
              {name} <FaChevronDown aria-hidden="true" />
            </button>
            <div className="oxy-float-panel" id={`oxy-float-menu-${index}`} hidden={open !== name} data-wide={name === "Resources"}>
              {Object.entries(groups).map(([category, links]) => <div key={category}>
                {name === "Resources" && <strong>{category}</strong>}
                {links.map(([label, url]) => {
                  if (url.startsWith("#")) return <a key={label} href={home + (preview ? url : originalSections[url] || url)} onClick={close}>{label}</a>;
                  if (url.startsWith("https:")) return <a key={label} href={url} target="_blank" rel="noopener noreferrer" onClick={close}>{label} ↗</a>;
                  return <Link key={label} to={destination(url)} onClick={close}>{label}</Link>;
                })}
              </div>)}
            </div>
          </div>
        ))}
        <Link to={destination("/contact-us")} onClick={close}>Contact Us</Link>
        <button type="button" className="oxy-float-rbi" onClick={() => { close(); onDirections(); }}>RBI Directions <FaExternalLinkAlt /></button>
      </nav>
      <PublicAccountActions />
    </header>
  </div>;
}
